#![allow(dead_code)]
mod sparse;mod scheduler;mod search_unused_marker {} mod bridge;mod bqi;mod check;mod continuation;
mod budget {
 include!("budget_core.rs");
 use crate::sparse::{Owner,Charge};
 impl Owner for Budget {
  fn reserve(&mut self,q:Charge)->Result<(),()>{let work=self.phase_native.work.checked_add(q.work).ok_or(())?;let bytes=self.phase_native.bytes.checked_add(q.bytes).ok_or(())?;self.observe(Reservation{work,bytes},Instant::now()).map_err(|_|())}
  fn check(&mut self)->Result<(),()>{Budget::check(self,Instant::now()).map_err(|_|())}
 }
 #[cfg(test)] mod tests {
 use super::*;use crate::{continuation::*,scheduler,check,bridge,bqi};
 fn limits()->Limits{Limits{partitions:64,work:100_000_000_000,bytes:100_000_000_000,search:scheduler::search::SearchLimits{nodes:32,native:scheduler::Limits{batch_rows:128,batch_ops:1024,batches:32,variables:256,generators:256,basis:256,tasks:1024,terms:256,proof:1024,degree:256,work:20_000_000,bytes:200_000_000}},audit:check::Limits{nodes:32,work:2_000_000_000,bytes:400_000_000,certificate:bridge::Limits{variables:256,generators:256,terms:256,degree:256,proof:1024,wire:65536,work:1_000_000_000,bytes:200_000_000},checker:bqi::Limits::software()}}}
 fn ready()->Budget{let now=Instant::now();let mut b=Budget::new(1024,128*1024*1024,4096,now+Duration::from_secs(20),now).unwrap();b.begin_native(false,now).unwrap();b.observe(Reservation{work:3,bytes:5},now).unwrap();b.finish_native(now).unwrap();b.begin_native(true,now).unwrap();b}
 #[test] fn four_candidates_share_actual_original_ledger_and_phase(){let mut b=ready();let id=b.ownership_id;let end=b.deadline;let mut s=Session::new(2,&[],limits(),end,&mut b);let mut models=Vec::new();loop{match s.next().unwrap(){Outcome::CandidateRetained=>{let call=s.with_candidate_owner(|model,deadline,owner|{assert_eq!(owner.ownership_id,id);assert_eq!(owner.deadline,deadline);assert_eq!(owner.phase,Phase::Matrix);owner.reserve_matrix_candidate_addition(Instant::now()).unwrap();model.to_vec()});assert_eq!(call.result,Ok(()));models.push(call.value.unwrap());s.exclude(models.len()as u64).unwrap();},Outcome::RemainingBooleanModelsExhaustedUnderRecordedExclusions=>break,_=>panic!("unexpected")}}let a=s.into_attempt();assert_eq!(models.len(),4);assert_eq!(models.iter().collect::<std::collections::BTreeSet<_>>().len(),4);assert_eq!(b.additions,4);assert_eq!(b.native.work,a.charge.work+3);assert_eq!(b.native.bytes,a.charge.bytes+5);assert_eq!(b.phase_native.work,a.charge.work);assert_eq!(b.phase,Phase::Matrix);assert_eq!(b.ownership_id,id);assert_eq!(b.deadline,end);}
 #[test] fn shared_addition_cap_stops_callback_without_excluding_candidate(){let mut b=ready();let end=b.deadline;let mut s=Session::new(1,&[],limits(),end,&mut b);assert_eq!(s.next(),Ok(Outcome::CandidateRetained));let call=s.with_candidate_owner(|_,_,owner|{let cap=owner.addition_limit;for _ in 0..cap{owner.reserve_matrix_candidate_addition(Instant::now()).unwrap();}owner.reserve_matrix_candidate_addition(Instant::now())});assert_eq!(call.value,Some(Err(Stop::Additions)));assert_eq!(call.result,Err(Failure::Owner));assert_eq!(s.exclude(0),Err(Failure::Owner));let a=s.into_attempt();assert_eq!(a.partitions[0].exclusion_record,None);assert_eq!(b.additions,b.addition_limit);assert_eq!(b.stopped,Some(Stop::Additions));assert_eq!(b.phase,Phase::Matrix);}
 #[test] fn actual_phase_ceiling_stops_later_search_without_reset(){let mut b=ready();let end=b.deadline;let mut s=Session::new(1,&[],limits(),end,&mut b);assert_eq!(s.next(),Ok(Outcome::CandidateRetained));let call=s.with_candidate_owner(|_,_,owner|{let prior=owner.phase_native;owner.observe(Reservation{work:prior.work,bytes:owner.phase_limits.bytes},Instant::now()).unwrap();owner.phase_limits.bytes});assert_eq!(call.result,Ok(()));let cap=call.value.unwrap();assert_eq!(s.exclude(0),Err(Failure::Owner));let a=s.into_attempt();assert_eq!(a.outcome,Outcome::Unknown);assert_eq!(b.phase_native.bytes,cap);assert_eq!(b.stopped,Some(Stop::Bytes));assert_eq!(b.phase,Phase::Matrix);assert!(b.native.bytes>a.charge.bytes);}
 }
}
